import { existsSync, readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

// Web test files of tasks without a green commit: the list `specs/pending-red.txt` is generated by tools/pending_red.py
// from the git history. vitest and playwright do not collect them (no skip marker is involved); a task's tests become
// mandatory the moment a [green] commit covers them and the list is regenerated.
const LIST = new URL("../specs/pending-red.txt", import.meta.url);

/** Paths relative to web/ of the pending web test files (an absent list means nothing is pending). */
export function pendingWebTests(): string[] {
  if (!existsSync(LIST)) return [];
  return readFileSync(LIST, "utf8")
    .split(/\r?\n/)
    .map((line) => line.trim())
    .filter((line) => line.startsWith("web/") && !line.startsWith("#"))
    .map((line) => line.slice("web/".length))
    .sort();
}

/** Prints the count and the list path once per run, so a CI log shows what was not collected. */
export function reportPending(runner: string): string[] {
  const files = pendingWebTests();
  console.log(
    `pending-red (${runner}): ${files.length} web test file(s) not collected (specs/pending-red.txt)`,
  );
  return files;
}

/** Absolute forward-slash paths of the pending web tests, the form playwright's `testIgnore` matches against. */
export function pendingAbsolute(runner: string): string[] {
  return reportPending(runner).map((f) => fileURLToPath(new URL(f, import.meta.url)).replaceAll("\\", "/"));
}
